<div class="play-tabs" role="group" aria-label="3D 玩法"><button type="button" data-play-mode="inspect" aria-pressed="true">① 看球怎麼轉</button><button type="button" data-play-mode="pitch" aria-pressed="false">② 來投一球</button><button type="button" data-play-mode="challenge" aria-pressed="false">③ 三星挑戰</button></div>
