function throwName(){return throwPitch==='custom'?spinTitles[spin]:pitchSpins.find(p=>p.id===throwPitch).name;}
function throwRPM(){return throwPitch==='custom'&&spin==='none'?0:rpm;}
function throwOptions(){
 if(throwPitch!=='custom')return pitchFlightOptions(throwPitch,throwHand,{speed,rpm,elevation,yaw});
 const axis=[...F.axes[spin]];if(throwHand==='left'){axis[1]*=-1;axis[2]*=-1;}
 return {axis,speed,rpm:throwRPM(),elevation,yaw};
}
function throwHint(){
 if(throwPitch==='custom')return spinTitles[spin]+' · 用四種基本旋轉做實驗。';
 const p=pitchSpins.find(p=>p.id===throwPitch);
 return p.rotation+(p.id==='knuckle'?' · 示範低旋轉，不模擬亂流飄移。':' · 已套用示範值，方向與速度可以再調。');
}
function loadThrowPitch(id){
 throwPitch=id;if(id==='custom')return;const p=pitchFlightOptions(id,throwHand);
 speed=p.speed;rpm=p.rpm;elevation=p.elevation;yaw=0;
}
function syncThrowChoices(){
 $('#throw-pitch').value=throwPitch;$('#throw-hand').value=throwHand;
 $('#throw-pitch-summary').textContent=throwHint();$('#play-speed').value=speed;$('#speed-value').textContent=speed+' 公里／時';
 $('#play-rpm').value=rpm;$('#play-rpm').disabled=throwPitch==='custom'&&spin==='none';$('#rpm-value').textContent=throwRPM()+' RPM';
 panel.querySelectorAll('[data-pitch-spin]').forEach(b=>b.setAttribute('aria-pressed',String(throwPitch==='custom'&&b.dataset.pitchSpin===spin)));
 if($('#aim-value'))$('#aim-value').innerHTML=aimLabel();
}
function bindThrowChoices(){
 $('#throw-pitch').onchange=e=>{loadThrowPitch(e.target.value);syncThrowChoices();resetShot();if(throwPitch==='custom')panel.querySelector('.dock-more').open=true;};
 $('#throw-hand').onchange=e=>{throwHand=e.target.value;syncThrowChoices();resetShot();};syncThrowChoices();
}

function aimLabel(){const right=camera?.matrixWorld.elements[0]<0?-1:1,visualYaw=yaw*right;return (yaw===0?'左右置中':visualYaw>0?'偏右 '+Math.abs(yaw).toFixed(1)+'°':'偏左 '+Math.abs(yaw).toFixed(1)+'°')+'<br>'+(elevation<0?'朝下 ':'朝上 ')+Math.abs(elevation).toFixed(1)+'°';}
function adjustAim(direction){let sign=camera?.matrixWorld.elements[0]<0?-1:1;if(Math.abs(camera?.matrixWorld.elements[0]||0)<.15)sign=1;if(direction==='left')yaw=Math.max(-4,yaw-.3*sign);if(direction==='right')yaw=Math.min(4,yaw+.3*sign);if(direction==='up')elevation=Math.min(8,elevation+.3);if(direction==='down')elevation=Math.max(-7,elevation-.3);yaw=Math.round(yaw*10)/10;elevation=Math.round(elevation*10)/10;$('#aim-value').innerHTML=aimLabel();resetShot();}

const fieldPad=document.createElement('div');fieldPad.className='world-pad';fieldPad.hidden=true;fieldPad.innerHTML='<span>箭頭瞄準</span><div><button type="button" data-field-aim="left" aria-label="球場瞄準向左">←</button><button type="button" data-field-aim="up" aria-label="球場瞄準向上">↑</button><button type="button" data-field-aim="down" aria-label="球場瞄準向下">↓</button><button type="button" data-field-aim="right" aria-label="球場瞄準向右">→</button></div>';world.append(fieldPad);fieldPad.querySelectorAll('button').forEach(b=>b.onclick=()=>panel.querySelector('[data-aim="'+b.dataset.fieldAim+'"]').click());
