function bindPanel(){bindAirButton();organizePanel();if(mode!=='inspect')bindThrowChoices();if(mode==='inspect'){buildSpinConsole();panel.querySelectorAll('[data-spin-pitch]').forEach(b=>b.onclick=()=>selectInspectPitch(b.dataset.spinPitch));}panel.querySelectorAll('[data-inspect]').forEach(b=>b.onclick=()=>inspect(b.dataset.inspect));panel.querySelectorAll('[data-inspect-spin]').forEach(b=>b.onclick=()=>{spin=b.dataset.inspectSpin;auto=spin!=='none';panel.innerHTML=panelHTML();bindPanel();$('#inspect-message').textContent=spin==='none'?'停住看一看：球沒轉，重力依然會拉它。':{back:'從球往前飛的側面看：後旋，球的頂部朝後翻。',top:'前旋，球的頂部朝前翻；換個角度，方向仍然一樣。',side:'側旋，旋轉軸改成上下方向，球往旁邊轉。'}[spin];});$('#inspect-next')?.addEventListener('click',()=>{loadThrowPitch(inspectPitch);throwHand=inspectHand;rpm=inspectRpm;setMode('pitch');});panel.querySelectorAll('[data-pitch-spin]').forEach(b=>b.onclick=()=>{throwPitch='custom';spin=b.dataset.pitchSpin;syncThrowChoices();resetShot();});$('#play-speed')?.addEventListener('input',e=>{speed=Number(e.target.value);$('#speed-value').textContent=speed+' 公里／時';resetShot();});$('#play-rpm')?.addEventListener('input',e=>{rpm=Number(e.target.value);$('#rpm-value').textContent=throwRPM()+' RPM';resetShot();});panel.querySelectorAll('[data-aim]').forEach(b=>b.onclick=()=>adjustAim(b.dataset.aim));$('#aim-reset')?.addEventListener('click',()=>{yaw=0;elevation=mode==='challenge'?-1.7:throwPitch==='custom'?-1.7:pitchDefaults[throwPitch].elevation;$('#aim-value').innerHTML=aimLabel();resetShot();});$('#play-slow')?.addEventListener('change',e=>{slow=e.target.checked;});$('#play-big')?.addEventListener('change',e=>{big=e.target.checked;ball.scale.setScalar(F.constants.radius*(big?4:1));ghostBall.scale.setScalar(F.constants.radius*(big?4:1));renderOnce();});$('#play-compare')?.addEventListener('change',e=>{compare=e.target.checked;resetShot();});$('#play-throw')?.addEventListener('click',()=>{if(playing){$('#play-pause').click();return;}if(mode==='challenge'&&mission===3){mission=0;updateGoal();$('#play-throw').textContent='投一球！ ↗';$('#play-result').textContent='再來一輪。第 1 關：正中手套。';return;}launch(false);});$('#play-replay')?.addEventListener('click',()=>launch(true));$('#play-pause')?.addEventListener('click',()=>{paused=!paused;$('#play-pause').textContent=paused?'繼續播放':'暫停';});}
function inspect(kind){inspected.add(kind);if(kind==='seam'){seamOn=!seamOn;ball.userData.thread.color.set(seamOn?'#ed5944':'#b32b27');ball.userData.thread.emissive.set(seamOn?'#46120d':'#000000');orbit.radius=3.25;auto=false;}if(kind==='leather'){orbit.radius=2.65;auto=false;ballPivot.rotation.set(.1,.25,.6);}if(kind==='turn'){auto=!auto;orbit.radius=4.2;}panel.innerHTML=panelHTML();bindPanel();panel.querySelector('.ball-details').open=true;$('#inspect-message').textContent={seam:'摸到了！紅色針腳跨過兩片皮革的交界，線比皮面稍高。真正投球時，指腹可以靠它抓穩。',leather:'靠近看：白色皮革有細小凹凸，並不是光滑的塑膠。小孔在縫線兩旁，紅線從孔裡穿過。',turn:auto?'球慢慢轉起來了。拖曳換個角度，看看同一條縫線怎麼繞過球背面。':'球停住了，可以慢慢找縫線。'}[kind];positionCamera();renderOnce();}
function stopAuto(){auto=false;const button=panel.querySelector('[data-inspect="turn"]');if(button){button.setAttribute('aria-pressed','false');button.innerHTML='開始旋轉 <span>03 ↻</span>';syncSpinLabels();}}
function resetShot(){playing=false;paused=false;elapsed=0;flight=null;trail.visible=ghostTrail.visible=ghostBall.visible=false;ball.position.set(0,1.8,0);ball.quaternion.identity();shadow.visible=false;if($('#play-throw'))$('#play-throw').disabled=false;if($('#play-pause')){$('#play-pause').disabled=true;$('#play-pause').textContent='暫停';}if($('#play-replay'))$('#play-replay').disabled=true;$('#flight-time').textContent='—';$('#flight-speed').textContent='—';$('#flight-distance').textContent='16.5 m';$('#play-result').classList.remove('success');$('#play-result').textContent='方向調好了。投一球，再看看結果。';updateAim();renderOnce();}
function updateAim(){if(!arrow)return;const e=elevation*Math.PI/180,a=yaw*Math.PI/180;arrow.setDirection(new THREE.Vector3(Math.cos(e)*Math.sin(a),Math.sin(e),Math.cos(e)*Math.cos(a)));updatePrediction();}
function launch(replay){if(playing||!renderer)return;if(!replay){flight=F.simulate(throwOptions());ghostFlight=F.simulate({spin:'none',speed,rpm:0,elevation,yaw});scored=false;}if(!flight)return;elapsed=0;paused=false;playing=true;auto=false;world.scrollIntoView({block:'start',behavior:reduce.matches?'instant':'smooth'});ball.quaternion.identity();ballPivot.quaternion.identity();trail.geometry.dispose();trail.geometry=new THREE.BufferGeometry().setFromPoints(flight.points.map(p=>new THREE.Vector3(p.x,p.y,p.z)));trail.geometry.setDrawRange(0,1);trail.visible=true;ghostTrail.geometry.dispose();ghostTrail.geometry=new THREE.BufferGeometry().setFromPoints(ghostFlight.points.map(p=>new THREE.Vector3(p.x,p.y,p.z)));ghostTrail.geometry.setDrawRange(0,1);ghostTrail.visible=compare;ghostBall.visible=compare;ghostBall.scale.setScalar(F.constants.radius*(big?4:1));$('#play-throw').disabled=true;$('#play-pause').disabled=false;$('#play-pause').textContent='暫停';$('#play-replay').disabled=true;$('#play-result').classList.remove('success');$('#play-result').textContent=(replay?'重播同一球。':throwName()+'出發！')+(slow?'現在放慢 8 倍；數字顯示球本身的飛行時間。':'現在是真實速度。');}
function finish(){playing=false;paused=false;$('#play-throw').disabled=false;$('#play-pause').disabled=true;$('#play-replay').disabled=false;const end=flight.end,target=targets[mode==='challenge'?Math.min(mission,2):0],hit=F.hit(end,target);if(mode==='challenge'&&!scored&&hit){mission++;scored=true;flashUntil=performance.now()+1800;celebrate(end);$('#play-result').classList.add('success');$('#play-result').textContent=mission===3?'三星集滿！你會先觀察，再調整方向了。還可以換一種旋轉，再挑戰一次。':'接到了！收集第 '+mission+' 顆星。下一個目標換了位置，看看要怎麼調整。';if(mission===3)$('#play-throw').textContent='集滿了！再挑戰 ↻';updateGoal();}else{const horizontal=(target.x-end.x)*(camera.matrixWorld.elements[0]<0?-1:1);const hint=[horizontal>.08?'往右一點':horizontal<-.08?'往左一點':'',end.y<target.y-.08?'往上一點':end.y>target.y+.08?'往下一點':''].filter(Boolean).join('、');const miss=mode==='challenge'?'離中心約 '+Math.round(Math.hypot(end.x-target.x,end.y-target.y)*100)+' 公分。試試'+(hint||'微調方向')+'。':`${throwName()}這一球，到達時高度 ${end.y.toFixed(2)} 公尺，左右偏移 ${Math.abs(end.x).toFixed(2)} 公尺。`;$('#play-result').textContent=end.z<F.constants.distance-.001?'這一球先碰地了。試試往上瞄準，或改變速度。':miss;}if(mode==='pitch'&&hit){$('#play-result').classList.add('success');$('#play-result').textContent='接到了！'+$('#play-result').textContent;celebrate(end);}}
function updateGoal(){if(!glove)return;const t=targets[mode==='challenge'?Math.min(mission,2):0];glove.position.set(t.x,t.y,16.57);goal.position.set(t.x,t.y,16.48);if(mode==='challenge'){$('#mission-stars').textContent='★'.repeat(mission)+'☆'.repeat(3-mission);$('#mission-title').textContent=mission===3?'你是三星小投手！':'0'+(mission+1)+' · '+titles[mission];$('#mission-copy').textContent=mission===3?'同一個方向，換一種旋轉會怎樣？':'每次只調一點點，再投一球看看。';}updatePrediction();}
function leatherTexture(){const cvs=document.createElement('canvas');cvs.width=cvs.height=512;const c=cvs.getContext('2d');c.fillStyle='#e3dac3';c.fillRect(0,0,512,512);let seed=91;const random=()=>((seed=(Math.imul(seed,1664525)+1013904223)|0)>>>0)/4294967296;for(let i=0;i<42000;i++){const x=random()*512,y=random()*512,r=.2+random()*.75;c.fillStyle=`rgba(${random()>.5?'255,253,237':'86,72,50'},${.05+random()*.12})`;c.beginPath();c.ellipse(x,y,r,r*.65,random()*6,0,Math.PI*2);c.fill();}const tex=new THREE.CanvasTexture(cvs);tex.wrapS=tex.wrapT=THREE.RepeatWrapping;tex.repeat.set(3,2);tex.colorSpace=THREE.SRGBColorSpace;return tex;}
