 const homeShape=new THREE.Shape();homeShape.moveTo(-.216,16.25);homeShape.lineTo(.216,16.25);homeShape.lineTo(.216,16.48);homeShape.lineTo(0,16.7);homeShape.lineTo(-.216,16.48);homeShape.closePath();const plate=mesh(new THREE.ShapeGeometry(homeShape),0xf1ead7);plate.rotation.x=Math.PI/2;plate.position.y=.022;f.add(plate); // Shape z follows positive field direction after rotation.
